//! Official Google Material Symbols Outlined resolution-independent MSDF system icons (68 icons).
//!
//! Source: https://github.com/google/material-design-icons (Apache-2.0, pinned rev `10ecc14790612ca8fd164e3f4ffe9c16fc50d5b7`)
//! Generated by `tools/msdf-icon-gen` (`fdsm` 0.8 pure-Rust Chlumsky MSDF generator) into
//! `codes/libs/ui/libbhoo/assets/material-system/icons.msdf` (48x48 3-channel MSDF, `px_range = 4.0`).
//!
//! - On GLES (`feature = "gles"`): uploads one 48x48 MSDF per `SystemIcon` to the GPU image atlas
//!   (68 slots total, regardless of color/opacity) and evaluates `median(r,g,b)` + `fwidth` in the
//!   fragment shader for razor-sharp vector edges at any size or zoom factor.
//! - On non-GLES backends (`bhoo-web` Canvas 2D / CPU): evaluates the embedded MSDF via bilinear
//!   median reconstruction into a cached 96x96 RGBA `Image`.

use crate::{Color, Frame, Image, ImageFit, Rect};
use std::collections::HashMap;
use std::sync::{Mutex, OnceLock};

const SYS_ICON_RASTER_SIZE: u32 = 96;
const SYS_SVG_COUNT: usize = 68;
const SYS_MSDF_BLOB: &[u8] = include_bytes!("../../assets/material-system/icons.msdf");

